149	  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
150	  const canGoBack = currentPageStart > 0;
151	  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;
152	
153	  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
154	  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));
