218	              onClick={handleNextPage}
219	              disabled={!canGoForward}
220	              aria-label={intl.formatMessage(NEXT_PAGE_MESSAGE)}
221	            >
222	              <ZimmIcon type="chevron-right" size="md" aria-hidden={true} />
