244	                key={value.value}
245	                name={value.name}
246	                imageUrl={value.imageUrl}
247	                href={value.href}
248	                isSelected={isSelected}
249	                isFocusable={isFocusable}
250	              />
251	            );
252	          })}
253	        </chakra.div>
254	      )}
255	    </chakra.div>
