import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useIntl } from 'react-intl';
import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
import { ZimmIcon } from '../../atoms/zimmIcon';

const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';

/**
 * Fixed page size once pagination kicks in — Figma's own interaction annotation on this node:
 * "Pagination appears if there are more than 4 swatches."
 */
const SWATCHES_PER_PAGE = 4;

/*
 * Reused verbatim from base SFCC's own swatch-group/index.jsx, the same way
 * zimmProductStyleCode/index.tsx reuses its own base-template label id — so this stays
 * consistent with base's i18n key rather than fragmenting translation keys. `values={{label}}`
 * interpolates the SFCC attribute display name (e.g. "Colour") passed in as this component's own
 * `label` prop.
 */
const GROUP_LABEL_MESSAGE = {
  id: 'swatch_group.selected.label',
  defaultMessage: '{label}:',
};

/*
 * Base SFCC's own SwatchGroup has no pagination at all, so these two have no base id to reuse —
 * new, Zimmermann-only ids.
 */
const PREVIOUS_PAGE_MESSAGE = {
  id: 'zimm_colour_swatch_group.pagination.previous',
  defaultMessage: 'Previous colours',
};
const NEXT_PAGE_MESSAGE = {
  id: 'zimm_colour_swatch_group.pagination.next',
  defaultMessage: 'Next colours',
};

/**
 * One selectable colour variation, as the caller (the PDP page) resolves it from SFCC's own
 * variation-attribute values.
 */
export type ZimmColourSwatchValue = {
  /** SFCC variation-attribute value, e.g. "BAYBL" — the identity matched against `selectedValue`. */
  value: string;
  /** Colour display name, e.g. "Bay Blue". Rendered as the dynamic label text and, via the atom, each swatch's accessible name. */
  name: string;
  /** Destination URL for this colour. Absent for the quick-view-modal path — see ZimmColourSwatch. */
  href?: string;
  /**
   * Fully resolved swatch-fill image URL. Undefined means this colour's index image is not
   * populated (AC 5) — such a value is filtered out before rendering and never surfaced to the
   * shopper, regardless of any stock/orderability field it might otherwise carry.
   */
  imageUrl?: string;
};

/** A colour value that has passed the AC-5 image-populated filter below. */
type PopulatedSwatchValue = ZimmColourSwatchValue & { imageUrl: string };

type ZimmColourSwatchGroupProps = {
  /**
   * SFCC attribute display name, e.g. "Colour" — interpolated into the "{label}:" text and used
   * as the swatches `radiogroup`'s aria-label.
   */
  label: string;
  /** Display name of the currently selected colour, e.g. "Bay Blue". */
  selectedName?: string;
  /** SFCC variation-attribute value of the currently selected colour, e.g. "BAYBL". */
  selectedValue?: string;
  /** Every selectable colour value for this attribute, populated or not — this component performs its own AC-5 filter. */
  values: readonly ZimmColourSwatchValue[];
};

/**
 * Molecule — the PDP colour-swatch group: the "Colour: Bay Blue" label row, and — once there is
 * more than one populated colour — the row of clickable colour swatches beneath it.
 *
 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not here.
 *
 * Three ACs live here as branch logic:
 *   - AC 5: a colour whose index image is not populated is filtered out before rendering and
 *     never surfaced to the shopper. Content-population, not stock/orderability — the filter
 *     keys on `imageUrl` alone.
 *   - AC 1: filtering *then* counting means an unpopulated colour never counts toward "there are
 *     multiple colours" — one populated colour (or zero) renders the label row only, with no
 *     `swatches` node and no `radiogroup` role at all.
 *   - Pagination: more than 4 populated colours paginates in fixed 4-wide windows. Paging moves
 *     the window only, never the selection — a selected colour that pages out of view stays
 *     selected, it is just not visible until paged back into view.
 *
 * @param props see ZimmColourSwatchGroupProps
 */
export const ZimmColourSwatchGroup = ({ label, selectedName, selectedValue, values }: ZimmColourSwatchGroupProps) => {
  const intl = useIntl();
  const swatchesRef = useRef<HTMLDivElement>(null);

  // AC 5. Lives here, not at the page level, because this component's own test file is where its
  // contract must be provable — the PDP page has no test file of its own. A type predicate
  // rather than a `!` at the call site below: TypeScript then knows every entry of `populated`
  // genuinely carries a string `imageUrl`, with no unchecked assertion needed.
  const populated = values.filter((value): value is PopulatedSwatchValue => Boolean(value.imageUrl));

  // The page that actually contains the current selection, recomputed fresh every render from
  // `populated`/`selectedValue` — never a second, independently-drifting copy of "where the
  // selection is." -1 (no match, or nothing selected yet) falls back to page 1, matching the
  // existing no-selection behaviour.
  const selectedIndex = populated.findIndex((value) => value.value === selectedValue);
  const selectedPageStart =
    selectedIndex === -1 ? 0 : Math.floor(selectedIndex / SWATCHES_PER_PAGE) * SWATCHES_PER_PAGE;

  // Seeded from `selectedPageStart` so the very first render already lands on the selection's
  // real page — React only consumes this argument on mount, so this alone covers first render.
  // It is not enough on its own once mounted: if `selectedValue`/`populated` change afterwards,
  // this initial value would go stale, because `pageStart` gates which items are even rendered,
  // not just which one shows a highlight — unlike base SFCC's own per-render-derived
  // `isFocusable`, which only ever affects a highlight on whatever is already on screen. The
  // effect below is what keeps `pageStart` correct for the lifetime of an already-mounted
  // instance.
  const [pageStart, setPageStart] = useState(selectedPageStart);

  // Resyncs `pageStart` to the selection's own page whenever `selectedPageStart` itself changes —
  // i.e. whenever a `selectedValue`/`populated` prop update moves the selection to a different
  // page on an already-mounted instance. Manual prev/next clicks (handlePrevPage/handleNextPage
  // below) only ever set `pageStart` directly and never touch `selectedPageStart`, so this effect
  // does not re-run on a manual page click and manual paging keeps working exactly as before in
  // between selection changes.
  useEffect(() => {
    setPageStart(selectedPageStart);
  }, [selectedPageStart]);

  const isPaginated = populated.length > SWATCHES_PER_PAGE;

  // Resolved here — once `isPaginated` is known — rather than at the top of this component: the
  // recipe needs it up front so the `swatches` part can reserve a fixed page-width footprint once
  // paginated, so the whole component doesn't visibly resize between a full page and a shorter
  // final page. See zimmColourSwatchGroup.css.ts's own comment on the `swatches` part for the
  // layout bug this fixes. Still an unconditional hook call — nothing above this point returns
  // early — so this reordering doesn't break the Rules of Hooks.
  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });

  // Defensive clamp, not part of any AC: if `values` shrinks while this instance stays mounted
  // (no remount), a stale `pageStart` left over from a longer list would otherwise slice to an
  // empty window with no swatches rendered at all.
  const lastPageStart = Math.max(0, Math.ceil(populated.length / SWATCHES_PER_PAGE) - 1) * SWATCHES_PER_PAGE;
  const currentPageStart = Math.min(pageStart, lastPageStart);
  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
  const canGoBack = currentPageStart > 0;
  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;

  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));

  /*
   * Roving focus across the *rendered* swatches, mirroring base SFCC's own
   * swatch-group/index.jsx onKeyDown (ArrowUp/ArrowLeft = backward, ArrowDown/ArrowRight =
   * forward, wrapping at the ends via modulus). Deliberately moves DOM focus only, via
   * `.focus()` on the sibling node, rather than touching `isFocusable`/selection state the way
   * base's own version does: there is no onVariationChange-equivalent prop here for an arrow
   * press to call (product-detail, Step 4, passes none yet), so there is nothing to trigger
   * beyond moving which element has focus. Activation stays the anchor's native Enter key,
   * inherited for free from the atom's ColourSwatchLink. Space does not activate an anchor
   * element — a native browser/HTML behaviour, not a bug, and an inherited parity gap versus a
   * true native radio input rather than a new regression introduced here.
   */
  const handleSwatchesKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const { key } = event;
    if (key !== 'ArrowUp' && key !== 'ArrowDown' && key !== 'ArrowLeft' && key !== 'ArrowRight') return;
    event.preventDefault();
    const container = swatchesRef.current;
    if (!container) return;
    const items = Array.from(container.children) as HTMLElement[];
    if (items.length === 0) return;
    const direction = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
    const activeIndex = items.indexOf(document.activeElement as HTMLElement);
    const fromIndex = activeIndex === -1 ? 0 : activeIndex;
    const nextIndex = (fromIndex + direction + items.length) % items.length;
    items[nextIndex]?.focus();
  };

  return (
    <chakra.div __css={styles.root} data-testid="colour-swatch-group">
      <chakra.div __css={styles.label}>
        {/*
          The label-group (the two "Colour:"/name text pieces) has no dedicated recipe part —
          only `labelName`, the piece that actually truncates, does. This wrapper's layout (flex
          row, 4px internal gap, flex: 1 0 0 so the pagination controls are pushed to the right)
          is expressed as direct Chakra props with var(--zimm-*) values instead: it is a
          structural, one-off layout wrapper with no competing or interactive style definitions of
          its own, so overrideStyling.md's "one canonical styling surface per component type" rule
          — scoped to components with competing/interactive style definitions — does not clearly
          apply here, and a dedicated recipe part would only exist to hold a single fixed flex-row
          layout that nothing else varies.
        */}
        <chakra.div display="flex" alignItems="center" gap="var(--zimm-scale-2xs)" flex="1 0 0" minWidth={0}>
          <chakra.span textStyle="caption" color="var(--zimm-color-text-default)" flexShrink={0}>
            {intl.formatMessage(GROUP_LABEL_MESSAGE, { label })}
          </chakra.span>{' '}
          <chakra.span __css={styles.labelName}>{selectedName}</chakra.span>
        </chakra.div>

        {isPaginated && (
          <chakra.div __css={styles.pagination}>
            <chakra.button
              type="button"
              __css={styles.pageButton}
              onClick={handlePrevPage}
              disabled={!canGoBack}
              aria-label={intl.formatMessage(PREVIOUS_PAGE_MESSAGE)}
            >
              <ZimmIcon type="chevron-left" size="md" aria-hidden={true} />
            </chakra.button>
            <chakra.button
              type="button"
              __css={styles.pageButton}
              onClick={handleNextPage}
              disabled={!canGoForward}
              aria-label={intl.formatMessage(NEXT_PAGE_MESSAGE)}
            >
              <ZimmIcon type="chevron-right" size="md" aria-hidden={true} />
            </chakra.button>
          </chakra.div>
        )}
      </chakra.div>

      {populated.length > 1 && (
        <chakra.div
          __css={styles.swatches}
          ref={swatchesRef}
          role="radiogroup"
          aria-label={label}
          onKeyDown={handleSwatchesKeyDown}
        >
          {windowed.map((value, index) => {
            const isSelected = value.value === selectedValue;
            // Base SFCC's own exact roving-tabindex rule (product-view/index.tsx's
            // renderDefaultVariationAttribute) — applied over the rendered *window*, since only
            // a rendered element can ever be a real focus target.
            const isFocusable = isSelected || (!selectedValue && index === 0);
            return (
              <ZimmColourSwatch
                key={value.value}
                name={value.name}
                imageUrl={value.imageUrl}
                href={value.href}
                isSelected={isSelected}
                isFocusable={isFocusable}
              />
            );
          })}
        </chakra.div>
      )}
    </chakra.div>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP colour-swatch group — the "Colour: Bay Blue" label row, and (when there is
 * more than one populated colour) the row of ZimmColourSwatch rectangles beneath it. This recipe
 * only lays the group out; each swatch's own fill/border/focus styling stays in the sibling
 * ZimmColourSwatch atom's own recipe.
 *
 * Values below are read directly off Figma for this exact component, not estimated — node
 * 40000307:13867 ("ColourOptions"), within Zimmermann_Design_System_2026.
 *
 * Six parts:
 *   - `root` — outer vertical flex container: the label row above, the swatches row below.
 *     Capped to a fixed `maxWidth` (`GROUP_RESERVED_WIDTH`, see below) unconditionally — not just
 *     when paginated — so `labelName`'s truncation CSS always has a definite width to truncate
 *     against. See this part's own baseStyle comment for the full explanation.
 *   - `label` — the label row ("labelContainer" in Figma): the label-group (the two
 *     "Colour:"/name text pieces — laid out via a plain Chakra-prop wrapper in the component
 *     itself, not a seventh part here; see index.tsx's own comment for why) plus the pagination
 *     controls, right-aligned purely via the label-group's own `flex: 1 0 0` rather than an
 *     absolute-position hack.
 *   - `labelName` — the dynamic colour-name text specifically (e.g. "Bay Blue"). Gets its own
 *     part, unlike the static "Colour:" piece beside it, because it alone carries the
 *     Figma-mandated truncation behaviour: "If Label/Colour name is longer, use truncation"
 *     (this node's own interaction annotation).
 *   - `swatches` — the horizontal row of rendered ZimmColourSwatch children. Once paginated
 *     (`isPaginated`), reserves a fixed page-width footprint regardless of how many items the
 *     current window actually renders — see its own baseStyle comment below for the layout bug
 *     this prevents.
 *   - `pagination` — wrapper around the two chevron buttons.
 *   - `pageButton` — each individual chevron button (24x24, holding a 16px ZimmIcon).
 */

/**
 * Matches `SWATCHES_PER_PAGE` in this component's own index.tsx (Figma's own interaction
 * annotation: "Pagination appears if there are more than 4 swatches"). Kept as its own literal
 * here rather than imported across files — this recipe stays a self-contained, co-located file,
 * the same precedent the sibling zimmColourSwatch.css.ts already sets for a state-dependent
 * baseStyle function. If `SWATCHES_PER_PAGE` in index.tsx ever changes, update this to match.
 */
const PAGE_SIZE = 4;

/**
 * The reserved 4-swatch-wide footprint: PAGE_SIZE swatches at the atom's own fixed 48px width
 * (`--zimm-scale-1200` — see zimmColourSwatch.css.ts's `swatch.width`), with no per-swatch gap
 * (`swatches.gap` below is 0, same as the atom's own adjacency). Two consumers share this one
 * value rather than each typing their own copy of the same `calc(...)` expression:
 *   - `swatches.width`/`minWidth`, applied only once paginated (see that part below) — keeps the
 *     footprint constant across a full page vs. a shorter final page.
 *   - `root.maxWidth`, applied unconditionally regardless of pagination (see that part below) —
 *     caps the whole component so `labelName`'s truncation CSS always has a definite width to
 *     truncate against.
 */
const GROUP_RESERVED_WIDTH = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;

export const ZimmColourSwatchGroup = {
  parts: ['root', 'label', 'labelName', 'swatches', 'pagination', 'pageButton'],

  baseStyle: ({ isPaginated }: { isPaginated?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      // 8px between the label row and the swatches row. No background here — background lives
      // per-swatch, already handled by the atom's own recipe.
      gap: 'var(--zimm-scale-xs)',
      // Unconditional cap, regardless of `isPaginated` — this is a bug fix, not a stylistic
      // choice. `root` otherwise has no width of its own (deliberate — see the `swatches` part
      // below for why a short, non-paginated row must still size naturally to its actual content)
      // so it has no ceiling for `labelName`'s truncation CSS to truncate against: confirmed via
      // real Chromium rendering that a long enough colour name simply grows `root` (and the
      // flex-grown `labelName` span inside it) past this footprint with no ellipsis, unless some
      // ancestor happens to impose a definite width of its own. Capping `root` itself to the same
      // reserved footprint `swatches` already reserves once paginated makes truncation
      // self-contained in every context, rather than depending on whatever the eventual PDP page
      // does or doesn't constrain. `maxWidth`, not `width`: `root` must still be free to render
      // narrower than this when content is short (e.g. one or two short colour names) — this only
      // ever stops it from growing past the cap. Does not change the swatches row's own sizing
      // behaviour (still `100%` when non-paginated, see below) — it only changes what that `100%`
      // now resolves against.
      maxWidth: GROUP_RESERVED_WIDTH,
    },

    label: {
      display: 'flex',
      alignItems: 'center',
      // 24px. Matches spacing.xl exactly, so the named step is used rather than the numerically
      // identical --zimm-scale-600 alias — see bottomBar.css.ts's own `var(--zimm-scale-xl)`
      // usage for the same 24px value elsewhere in this codebase.
      height: 'var(--zimm-scale-xl)',
      // 8px between the label-group and the pagination controls.
      gap: 'var(--zimm-scale-xs)',
    },

    labelName: {
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
      // The truncating half of the label-group's two text pieces (the static "Colour:" text
      // beside it never truncates — see index.tsx). `flex: 1 0 0` lets it consume the
      // label-group's remaining width; `minWidth: 0` is required for a flex item to actually
      // shrink below its content size instead of overflowing; the rest is the standard
      // single-line-ellipsis triad.
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
    },

    swatches: {
      display: 'flex',
      // Non-paginated (<= SWATCHES_PER_PAGE populated colours): sizes naturally to however many
      // swatches are actually present. Unchanged, deliberately out of scope for this fix — there
      // is no confirmed design value either way for a 2- or 3-colour row's width, so nothing was
      // invented here.
      //
      // Paginated (> SWATCHES_PER_PAGE populated colours, windowed to a fixed PAGE_SIZE-wide
      // slice per page): a plain `100%` here resolves against `root`'s own width — but `root` has
      // no explicit width of its own, so it auto-fits to its widest child, which is this very
      // element. That circular relationship meant the *rendered* width tracked how many items the
      // current window actually held (192px for a full 4-item page, 96px for a 2-item final
      // page), so `root` — and `label` above it, itself 100% of that same `root` — visibly
      // resized between pages. Confirmed directly in a running Storybook: the pagination chevrons
      // jumped position between the two pages of the `Paginated` story. Reserving
      // GROUP_RESERVED_WIDTH regardless of the current page's real item count breaks that
      // loop — the footprint stays constant across every page, full or partial. A partial final
      // page's unused space simply remains empty to the right: the flex default
      // `justify-content: flex-start` already left-aligns the rendered items, so nothing further
      // is needed for that.
      width: isPaginated ? GROUP_RESERVED_WIDTH : '100%',
      ...(isPaginated ? { minWidth: GROUP_RESERVED_WIDTH } : {}),
      // Confirmed directly off the Figma export, not a stylistic default: the 4-swatch example
      // measures exactly 192px total width for four 48px-wide swatches (4 x 48, no gap
      // contribution) — swatches sit directly adjacent. Do not add a gap here; that would be a
      // real deviation from the design, not a stylistic default.
      gap: 0,
    },

    pagination: {
      display: 'flex',
      alignItems: 'center',
      // No inter-button gap value exists in the Figma export handed to this step — left at the
      // flex default (no `gap` declared at all) rather than invented. Revisit if a designer
      // confirms a real value.
    },

    pageButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-xl)', // 24px
      height: 'var(--zimm-scale-xl)', // 24px
      // Resets the native <button> UA chrome so the box is exactly the 24x24 the design calls
      // for, with the 16px ZimmIcon centred inside it by the flex alignment above.
      padding: 0,
      border: 'none',
      background: 'none',
      cursor: 'pointer',
      // No confirmed Figma spec for a disabled visual treatment on this control — same "leave an
      // unspecified visual state alone rather than invent one" precedent as swatch-group's own
      // disabled colour logic (see this codebase's Known Gaps notes). The native `disabled`
      // attribute (set in index.tsx) already makes the control genuinely inert and announces as
      // disabled to assistive tech; only the cursor affordance is set here, which is a UX
      // keyword, not a design token.
      _disabled: {
        cursor: 'not-allowed',
      },
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem) — --zimm-focus-ring already composites the border-width/colour pair.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

