135	    // the fix, `pageStart` always started at 0 regardless of where the selection sat, so this
136	    // exact shape rendered page 1 (indices 0-3) with zero items aria-checked and zero items
137	    // tabbable, since the selected colour was never part of the rendered window.
138	    const SIXTH_COLOUR: ZimmColourSwatchValue = {
