152	
153	    // No interaction of any kind above this line — this asserts the component's very first render.
154	    renderGroup({ selectedName: SIXTH_COLOUR.name, selectedValue: SIXTH_COLOUR.value, values: sixColours });
155	
156	    const radios = screen.getAllByRole('radio');
