170	    // 6 populated colours -> paginated (> SWATCHES_PER_PAGE = 4): page 1 renders a full 4-swatch
171	    // window, the final page only the remaining 2. Before the fix, `swatches` was a plain `100%`
172	    // of `root`, and `root` itself has no explicit width — it auto-fits to its widest child,
173	    // which is `swatches` itself. That circular relationship meant the rendered footprint tracked
174	    // how many items the current window actually held, so `root` (and `label` above it, itself
175	    // 100% of that same `root`) visibly resized between pages — confirmed directly in a running
176	    // Storybook, where the pagination chevrons jumped position between the two pages of the
177	    // `Paginated` story.
178	    const sixColours: ZimmColourSwatchValue[] = [
179	      BAY_BLUE,
180	      IVORY,
181	      BLACK,
182	      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
183	      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
184	      { value: 'NAVY', name: 'Navy', href: '/p.html?color=NAVY', imageUrl: IMAGE('navy') },
185	    ];
186	
187	    renderGroup({ selectedName: BAY_BLUE.name, selectedValue: BAY_BLUE.value, values: sixColours });
188	    expect(screen.getAllByRole('radio')).toHaveLength(4);
189	
190	    // jsdom has no real layout engine — getBoundingClientRect() reads 0 for every element
191	    // regardless of whether the fix is applied, which would make a before/after comparison pass
192	    // even against the pre-fix code (a false negative that proves nothing). getComputedStyle
193	    // *does* reliably read back the literal declared CSS value for a Chakra/emotion-authored
194	    // style in this codebase's jsdom setup — the same technique the "resolves its recipe under a
195	    // ChakraProvider" test above already relies on for `gap`.
196	    const widthBefore = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;
197	
