199	    // rather than just compared against the post-click reading. A plain `100%` is ALSO textually
200	    // identical to itself before and after clicking "next" (the literal declared string never
201	    // changes; only what it resolves against would, which jsdom cannot compute). Without this,
202	    // a same-value-both-times check alone would pass against the pre-fix code too and would not
203	    // actually catch the regression.
204	    const PAGE_SIZE = 4;
205	    const expectedWidth = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;
