210	
211	    // Now on the final, partial (2-item) page.
212	    expect(screen.getAllByRole('radio')).toHaveLength(2);
213	
214	    const widthAfter = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;
