216	    expect(widthAfter).not.toBe('100%');
217	  });
218	
219	  test('caps root to the reserved 4-swatch footprint so a long colour name has something to truncate against (layout regression)', () => {
220	    // Before the fix, `root` had no width of its own at all — deliberate, so a short,
221	    // non-paginated row still sizes naturally to its actual content (see the `swatches` part's own
222	    // comment) — which meant it also had no ceiling for `labelName`'s truncation CSS to truncate
223	    // against. Confirmed directly via real Chromium/Storybook rendering: a 70-character colour
224	    // name grew `root` to ~390px (its own widest-child shrink-to-fit width) with the name
225	    // rendering in full — `getComputedStyle(root).maxWidth` read back literally `none` in that
226	    // broken state. Capping `root.maxWidth` to the same reserved 4-swatch footprint `swatches`
227	    // already reserves once paginated fixes this unconditionally, not just when paginated — see
228	    // the next test for the paginated case.
229	    const LONG_NAME = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
230	    renderGroup({ selectedName: LONG_NAME, selectedValue: 'BAYBL' });
231	
232	    const rootStyles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
233	    const PAGE_SIZE = 4;
